{
  "name": "@ongyishen/opencode-notifier-ntfy",
  "version": "1.0.2",
  "description": "OpenCode plugin that sends ntfy notifications when permission is needed, generation completes, or errors occur",
  "author": "ongyishen",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ongyishen/opencode-notifier-ntfy.git"
  },
  "homepage": "https://github.com/ongyishen/opencode-notifier-ntfy#readme",
  "bugs": {
    "url": "https://github.com/ongyishen/opencode-notifier-ntfy/issues"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node",
    "prepublishOnly": "bun run build",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notifications",
    "ntfy",
    "alerts"
  ],
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.224",
    "@types/node": "^22.0.0",
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  }
}
